    supports={k:sorted({h for v in bag for h in c['boundary_attachments'][v]}) for k,bag in c['pieces'].items()}
    print(json.dumps({'id':c['id'],'valid_expected':c['expected_valid'],'C_edges':c['original_edges'],'blocks':c['blocks'],'pieces_after_r':comps,'degree_totals':totals,'supports':supports,'r_contacts':c['r_contacts'],'s_contacts':c['s_contacts'],'rotation_neighbor_match':rot,'actual_U':c['actual_U_supplied'],'actual_G':c['actual_G_supplied']},ensure_ascii=False))
